import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const root = new URL("../", import.meta.url);
const sources = ["skin.css", "framework.css", "offline.css"];
const target = new URL("services/api/vks_api/reader_assets/handbook.css", root);
const css =
  "/* Generated by scripts/reader_handbook.mjs from the clean handbook package. */\n" +
  (
    await Promise.all(
      sources.map((name) =>
        readFile(
          new URL("packages/handbook-template/src/" + name, root),
          "utf8",
        ),
      ),
    )
  ).join("\n");
if (process.argv.includes("--check")) {
  if ((await readFile(target, "utf8").catch(() => "")) !== css)
    throw new Error(
      "Handbook CSS is stale: run node scripts/reader_handbook.mjs",
    );
} else {
  await writeFile(target, css);
  console.log("Generated " + fileURLToPath(target));
}
